"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9413],{39413:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/Thunderhead.png\\"\\n          title=\\"선더헤드 Thunderhead\\"\\n          author=\\"닐 셔스터먼\\"\\n          publisher=\\"열린책들\\"\\n          publishedDate=\\"2023-02-10\\"\\n          isbn=\\"9788932923055\\"\\n          rating=4.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n전작 <mark>수확자(Scythe)</mark>가 구축한 세계관을 비극적으로 확장하며, 그 세계가 품고 있던 철학적 질문의 깊이를 파고든다.  \\n<br>\\n인류가 죽음을 정복한 후 인구 조절을 위해 만들어진 ```수확자``` 시스템이 필연적으로 실패할 수밖에 없는 과정을 보여주는 것 같다.\\n<br>\\n기술적으로 완벽한 유토피아라고 해도, 전지전능한 AI가 의도적으로 통제하지 않는 상황이라면 인간의 어쩔 수 없는 야망과 잔인함, 그리고 권력욕에 의해 붕괴되는 것은 필연적이다.  \\n이는 인간의 역사에서 끊임없이 증명되고 있다.  \\n<br>\\n썬더헤드는 자신의 원칙에 묶여 사랑하는 인류가 비틀거리는 것을 속수무책으로 지켜봐야만 하는, 자비로운 신이다.  \\n인류를 위협하는 부패가 싹트는 것을 감지한 썬더헤드는 자신의 법을 어기지 않으면서 개입하기 위한 미묘한 계획을 실행한다.  \\n<br>\\n전작에서 완전한 유토피아인 줄 알았던 세상이 ```해결 불가능한 인간 변수```라는 내재적 결함이 있음을 보여준다.  \\n<br>\\n이제 다음 시리즈 <mark>종소리</mark>를 위한 무대가 완벽하게 마련되었다."}')}}]);